    private void jButtonAddActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonAddActionPerformed
        // TODO add your handling code here:
        String sProduct = jTextFieldProduct.getText();
        stackInterface.push(sProduct);
        jTextAreaDisplay.append("A new wagon with "+sProduct+" was added to the train\n");
        jTextFieldProduct.setText("");

    }//GEN-LAST:event_jButtonAddActionPerformed

    private void jButtonWagonNumbersActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonWagonNumbersActionPerformed
        // TODO add your handling code here:
        int iNumberOfWagons = stackInterface.size();
        jTextAreaDisplay.append("There are "+iNumberOfWagons+" in the trains\n");
        if(iNumberOfWagons>5){
            jTextAreaDisplay.append("There are more than 5, please remove "+(iNumberOfWagons-5)+"\n");
        }
    }//GEN-LAST:event_jButtonWagonNumbersActionPerformed

    private void jButtonRemoveActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonRemoveActionPerformed
        // TODO add your handling code here:
        String sProduct = (String)stackInterface.pop();
        
        if(sProduct == null) {
            jTextAreaDisplay.append("Cannot remove wagon, because the train has none\n");
        } else {
            jTextAreaDisplay.append("The wagon with "+sProduct+" was removed\n");
            jTextAreaDisplay.append("The wagon with "+stackInterface.size()+" wagons\n");  
        }
    }//GEN-LAST:event_jButtonRemoveActionPerformed

    private void jButtonRemoveAllActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonRemoveAllActionPerformed
        // TODO add your handling code here:
        stackInterface.emptyStack();
        jTextAreaDisplay.append("All wagons are gone\n");
                
    }//GEN-LAST:event_jButtonRemoveAllActionPerformed

    private void jButtonListWagonsActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonListWagonsActionPerformed
        // TODO add your handling code here:
        String sMessage = stackInterface.displayStack();
        jTextAreaDisplay.append(sMessage);
    }//GEN-LAST:event_jButtonListWagonsActionPerformed

